 record Fixture(String host,String a,String b,String cid,String eid,String rid,String pid){}
 static Fixture fixture(String mode)throws Exception {String suffix=UUID.randomUUID().toString();String host=user("h"+suffix),a=user("a"+suffix),b=user("b"+suffix);var c=club(host,"IMMEDIATE");String cid=text(c,"id");var e=event(host,cid,version(c),"LIGHTNING",true,mode);String eid=text(e,"id");var r=round(host,eid,version(e),3,false);String rid=text(r,"id");var p=post("/rounds/"+rid+"/participations",a,Map.of("version",version(r)));assertEquals(200,p.status);assertEquals(200,post("/events/"+eid+"/finance/open",host,Map.of("version",0,"mode",mode)).status);return new Fixture(host,a,b,cid,eid,rid,text(p,"id"));}
 static long fv(Fixture x)throws Exception{return version(get("/events/"+x.eid+"/finance",x.host));}
 static Reply billing(Fixture x,long amount,boolean closed)throws Exception {if(closed)context.getBean(org.springframework.jdbc.core.JdbcTemplate.class).update("update event_round set closes_at=now()-interval '1 minute' where id=?",UUID.fromString(x.rid));return post("/rounds/"+x.rid+"/payment-requests",x.host,Map.of("version",fv(x),"amount",amount,"deadline",Instant.now().plusSeconds(3600).toString()));}
 static String ownRequest(Fixture x)throws Exception{var reply=get("/events/"+x.eid+"/finance",x.a);assertEquals(200,reply.status,reply.body.toString());assertTrue(reply.body.path("requests").size()>0,reply.body.toString());return reply.body.path("requests").get(0).path("id").asText();}
 static void ended(Fixture x){context.getBean(org.springframework.jdbc.core.JdbcTemplate.class).update("update club_event set starts_at=now()-interval '2 hours',ends_at=now()-interval '1 hour' where id=?",UUID.fromString(x.eid));}
