 static String reviewMixedTiming(String personalTime,long deposit)throws Exception {
  var x=fixture("POSTPAY");String aid=text(get("/me",x.a),"id"),hid=text(get("/me",x.host),"id");var personal=new HashMap<String,Object>();personal.put("paidByUserId",aid);personal.put("source","PERSONAL");personal.put("amount",personalTime.equals("CORRECTED")?100:50);if(!personalTime.equals("UNKNOWN"))personal.put("actualPaidAt",Instant.now().minusSeconds(personalTime.equals("LATE")?30:120).toString());
  assertEquals(200,post("/events/"+x.eid+"/finance/expenses",x.host,Map.of("version",fv(x),"roundId",x.rid,"title","mixed contribution","amount",personalTime.equals("CORRECTED")?150:100,"fundings",List.of(personal,Map.of("paidByUserId",hid,"source","PERSONAL","amount",50,"actualPaidAt",Instant.now().minusSeconds(120).toString())) )).status);registerFunding(x);if(personalTime.equals("CORRECTED"))assertEquals(200,post("/events/"+x.eid+"/finance/revisions",x.host,Map.of("version",fv(x),"roundId",x.rid,"reason","partial personal expense correction without timestamp attribution","amount",-50,"fundings",List.of(Map.of("paidByUserId",aid,"source","PERSONAL","amount",-50)))).status);var sql=context.getBean(org.springframework.jdbc.core.JdbcTemplate.class);sql.update("update payment_request set deadline=now()-interval '60 seconds' where book_id=(select id from settlement_book where event_id=?)",UUID.fromString(x.eid));
  var report=post("/events/"+x.eid+"/finance/reports",x.a,Map.of("version",fv(x),"requestId",ownRequest(x),"amount",deposit));assertEquals(200,post("/events/"+x.eid+"/finance/reports/"+text(report,"id")+"/verify",x.host,Map.of("version",fv(x),"amount",deposit,"actualReceivedAt",Instant.now().minusSeconds(120).toString(),"transactionReference","mixed:"+text(report,"id"),"allocations",List.of(allocation(x,deposit,"ATTENDANCE")))).status);
  return sql.queryForObject("select outcome from platform_level where event_id=? and user_id=? and role='PARTICIPANT'",String.class,UUID.fromString(x.eid),UUID.fromString(aid));
 }
