 static void reviewPersonalTimeRevision(boolean initiallyLate)throws Exception {
  var x=fixture("POSTPAY");var sql=context.getBean(org.springframework.jdbc.core.JdbcTemplate.class);String aid=text(get("/me",x.a),"id"),bid=text(get("/me",x.b),"id"),hid=text(get("/me",x.host),"id");UUID event=UUID.fromString(x.eid),actor=UUID.fromString(aid),other=UUID.fromString(bid),host=UUID.fromString(hid);
  assertEquals(200,post("/rounds/"+x.rid+"/participations",x.b,Map.of("version",version(get("/rounds/"+x.rid+"/participation",x.a)))).status);
  Instant clock=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS),oldTime=clock.minusSeconds(initiallyLate?30:120),correctedTime=clock.minusSeconds(initiallyLate?120:30);
  assertEquals(200,post("/events/"+x.eid+"/finance/expenses",x.host,Map.of("version",fv(x),"roundId",x.rid,"title","two participants actual funded invoice","amount",200,"fundings",List.of(Map.of("paidByUserId",aid,"source","PERSONAL","amount",50,"actualPaidAt",oldTime.toString()),Map.of("paidByUserId",hid,"source","PERSONAL","amount",150,"actualPaidAt",clock.minusSeconds(120).toString())))).status);registerFunding(x);sql.update("update payment_request set deadline=? where book_id=(select id from settlement_book where event_id=?)",java.sql.Timestamp.from(clock.minusSeconds(60)),event);
  for(var payer:List.of(x.a,x.b)){String payerId=text(get("/me",payer),"id"),request="";for(var q:get("/events/"+x.eid+"/finance",payer).body.path("requests"))if(q.path("userId").asText().equals(payerId))request=q.path("id").asText();long amount=payer.equals(x.a)?50:100;var report=post("/events/"+x.eid+"/finance/reports",payer,Map.of("version",fv(x),"requestId",request,"amount",amount));assertEquals(200,post("/events/"+x.eid+"/finance/reports/"+text(report,"id")+"/verify",x.host,Map.of("version",fv(x),"amount",amount,"actualReceivedAt",clock.minusSeconds(120).toString(),"transactionReference","time-revision:"+text(report,"id"),"allocations",List.of(allocation(x,amount,"ATTENDANCE")))).status);}
  assertEquals(initiallyLate?-1:1,sql.queryForObject("select delta from platform_level where event_id=? and user_id=? and role='PARTICIPANT'",Integer.class,event,actor));int otherAudits=sql.queryForObject("select count(*) from platform_level_audit a join platform_level l on l.id=a.level_id where l.event_id=? and l.user_id=?",Integer.class,event,other),hostAudits=sql.queryForObject("select count(*) from platform_level_audit a join platform_level l on l.id=a.level_id where l.event_id=? and l.user_id=?",Integer.class,event,host);
  var revised=post("/events/"+x.eid+"/finance/revisions",x.host,Map.of("version",fv(x),"roundId",x.rid,"reason","explicit actual personal payment time correction","amount",0,"fundings",List.of(Map.of("paidByUserId",aid,"source","PERSONAL","amount",-50,"actualPaidAt",oldTime.toString()),Map.of("paidByUserId",aid,"source","PERSONAL","amount",50,"actualPaidAt",correctedTime.toString()))));assertEquals(200,revised.status,revised.body.toString());context.getBean(FinanceScoreSource.class).reassess(event);
  assertEquals(initiallyLate?1:-1,sql.queryForObject("select delta from platform_level where event_id=? and user_id=? and role='PARTICIPANT'",Integer.class,event,actor));assertEquals(1,sql.queryForObject("select delta from platform_level where event_id=? and user_id=? and role='PARTICIPANT'",Integer.class,event,other));assertEquals(2,sql.queryForObject("select delta from platform_level where event_id=? and user_id=? and role='HOST'",Integer.class,event,host));assertEquals(otherAudits,sql.queryForObject("select count(*) from platform_level_audit a join platform_level l on l.id=a.level_id where l.event_id=? and l.user_id=?",Integer.class,event,other));assertEquals(hostAudits,sql.queryForObject("select count(*) from platform_level_audit a join platform_level l on l.id=a.level_id where l.event_id=? and l.user_id=?",Integer.class,event,host));
 }
 @Test void reviewPersonalActualTimeCorrectionFromOnTimeToLateReplacesOnlyAffectedScore()throws Exception {reviewPersonalTimeRevision(false);}
 @Test void reviewPersonalActualTimeCorrectionFromLateToOnTimeReplacesOnlyAffectedScore()throws Exception {reviewPersonalTimeRevision(true);}
